import XCTest
import Foundation
@testable import AppleAccountKit
final class AppleSRPTests: XCTestCase {
    private func hex(_ value: String) -> Data {
        Data(stride(from: 0, to: value.count, by: 2).map { offset in
            let start = value.index(value.startIndex, offsetBy: offset)
            return UInt8(value[start..<value.index(start, offsetBy: 2)], radix: 16)!
        })
    }
    func testIndependentServerTranscriptAndProof() throws {
        // Generated by a separate Python SRP server (b, verifier, server-side S),
        // rather than a second call through this client implementation.
        let client = AppleSRP(privateKey: hex("0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20"))
        XCTAssertEqual(client.publicKey, hex(""))
        let answer = try client.answer(username: "fixture@example.invalid", password: hex("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f"), salt: hex("000102030405060708090a0b0c0d0e0f"), server: hex(""))
        XCTAssertEqual(answer.key, hex("8bb4fa66d43a023ab8bc4a6e9ac8111bd494d66e6a0cf7d87a29c9966f201884"))
        XCTAssertEqual(answer.proof, hex("7a42d13aa27e257af0f3334aa96a80ae6a90190b6a91032e90fee66b809a82a5"))
        XCTAssertEqual(answer.serverProof, hex("f2912b0420d11ca8eb60d5fa952703289e5c370a431bca08019d97975992b046"))
        XCTAssertNoThrow(try AppleSRP.verify(answer.serverProof, equals: answer.serverProof))
        XCTAssertThrowsError(try AppleSRP.verify(Data(repeating: 0, count: 32), equals: answer.serverProof))
    }
    func testRejectsInvalidServerKeysAndProofLengths() {
        let client = AppleSRP(privateKey: Data([1]))
        for server in [Data(), Data([0]), AppleSRP.pad(AppleSRP.modulus), Data(repeating: 255, count: 257)] {
            XCTAssertThrowsError(try client.answer(username: "fixture", password: Data([1]), salt: Data([1]), server: server))
        }
        XCTAssertThrowsError(try AppleSRP.verify(Data(), equals: Data(repeating: 0, count: 32)))
    }
    func testShortPublicValuesAndSharedSecretsUseProtocolByteLengths() throws {
        // Independent server transcripts: one S and one B have leading zero
        // octets at group width. A=2 is deliberately one byte on the wire.
        let client = AppleSRP(privateKey: Data([1]))
        XCTAssertEqual(client.publicKey, Data([2]))
        let transcripts: [(String,String,String,String)] = [
            ("", "e640f74dd75e368853f16c0c4981ac834cb5be7ab22aded08a40d20aede98cd5", "6c1580ec846eea1fdf98be319863c52aef712735f4280350f8e39b1a5410eb4c", "206338b07bc1f6c223ba035ddb1ba8e4c99b190a23a33637cba4f5036a719d1f"), // shortB, minimal S bytes=256
            ("", "4b362b71b4dc4b0ce0597dc65731e4738a0a43f741afd6866e9c1b32bf3deda0", "d96a66627d2548f6a6120612640523b34582baaee2d68d977f55dbc13cd72f01", "dd1d71529a2a32a191046b59456babb0569ef010baf59203d927673f28ef1d05"), // shortS, minimal S bytes=255
        ]
        for (server,key,proof,serverProof) in transcripts {
            let answer = try client.answer(username: "fixture@example.invalid", password: Data((0..<32).map(UInt8.init)), salt: Data((0..<16).map(UInt8.init)), server: hex(server))
            XCTAssertEqual(answer.key, hex(key))
            XCTAssertEqual(answer.proof, hex(proof))
            XCTAssertEqual(answer.serverProof, hex(serverProof))
        }
    }

}
